function EXTRA(R,ICON){
 /* hook: the weight hung gently, and the same weight dropped */
 ICON.mdHang=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${MD_box(0,0,380,170,{fill:'#FFFFFF',st:MD_GREY,sw:3,r:18})}
  ${MD_hang(80,24,96,0)}${MD_T(160,62,'10 kg, gently',{fs:24,fw:800,fill:BLU})}${MD_T(160,98,'stress',{fs:22,fill:MD_GREY})}${MD_T(160,134,'0.196 MPa',{fs:26,fw:800,fill:BLU})}</g>`;
 ICON.mdDrop=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${MD_box(0,0,380,170,{fill:'#FFFFFF',st:RED,sw:3,r:18})}
  ${MD_hang(80,24,96,60,{col:'#F4B183'})}${MD_dbl(36,76,36,120,RED,3)}${MD_T(160,62,'dropped 100 mm',{fs:24,fw:800,fill:RED})}${MD_T(160,98,'stress',{fs:22,fill:MD_GREY})}${MD_T(160,134,'88.8 MPa',{fs:26,fw:800,fill:RED})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.mdFos=(x,y)=>{const sx=v=>v/280*380;let s='';
  [['Syt',280,BLU],['allowable',112,ORG],['25 mm bar',91.7,GRN]].forEach(([n,v,col],i)=>{const yy=30+i*100;s+=MD_T(0,yy,n+' '+v,{fs:24,fw:800,fill:col})+`<rect x="0" y="${yy+12}" width="${sx(v)}" height="44" rx="5" fill="${col}" fill-opacity=".35" stroke="${col}" stroke-width="3"/>`});
  s+=MD_L(sx(112),10,sx(112),300,ORG,3,'stroke-dasharray="7 6"');
  return `<g transform="translate(${x-200} ${y-150})">${s}</g>`};
 ICON.mdLoads=(x,y)=>{let s='';const W=120,H=150,base=230;
  [[0,'static',BLU],[150,'dynamic',GRN],[300,'impact',RED]].forEach(([x0,n,col])=>{s+=MD_arrow(x0,base,x0+W,base,MD_DARK,3,10)+MD_arrow(x0,base,x0,base-H-20,MD_DARK,3,10)+MD_T(x0+W/2,base+36,n,{fs:24,fw:800,a:'middle',fill:col})});
  s+=MD_poly([[0,150],[110,150]],BLU,5);
  s+=MD_poly(MD_range(0,110,44).map(t=>[150+t,150-50*Math.sin(t/110*4*Math.PI)]),GRN,5);
  s+=MD_poly([[300,218],[340,218],[350,80],[360,218],[410,218]],RED,5);
  return `<g transform="translate(${x-205} ${y-150})">${s}</g>`};
 ICON.mdStress=(x,y)=>{let s='';const t=40,bt=280,m=160;
  s+=MD_L(60,t,60,bt,MD_DARK,2)+`<polygon points="60,${t} 20,${t} 20,${bt} 60,${bt}" fill="${BLU}" fill-opacity=".3" stroke="${BLU}" stroke-width="3"/>`+MD_T(40,bt+36,'direct',{fs:22,fw:800,a:'middle',fill:BLU});
  s+=MD_L(210,t,210,bt,MD_DARK,2)+`<polygon points="210,${t} 270,${t} 150,${bt} 210,${bt}" fill="${GRN}" fill-opacity=".3" stroke="${GRN}" stroke-width="3"/>`+MD_T(210,bt+36,'bending',{fs:22,fw:800,a:'middle',fill:GRN});
  s+=MD_L(350,t,350,bt,MD_DARK,2)+`<polygon points="350,${t} 400,${t} 350,${m} 300,${bt} 350,${bt}" fill="${ORG}" fill-opacity=".3" stroke="${ORG}" stroke-width="3"/>`+MD_T(350,bt+36,'torsion',{fs:22,fw:800,a:'middle',fill:ORG});
  return `<g transform="translate(${x-210} ${y-160})">${s}</g>`};
}
